(32,0,0,'一个充满爱的故事，我喜欢。','',1);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900025,'We have some test for you, since you have already study for a long time.$BIf you are ready, tell me.','We have some test for you, since you have already study for a long time.$BIf you are ready, tell me.');
