INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900278,'我遗失了我的鱼竿。','我遗失了我的鱼竿。'),
(900279,'让我一个人静一静。','让我一个人静一静。'),
(900280,'我的男朋友认为时间末日快到了。','我的男朋友认为时间末日快到了。');
