(355,0,900384,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900356,'那该死的咸鱼给我们惹了不少麻烦。','那该死的咸鱼给我们惹了不少麻烦。'),
(900357,'我可不信任领主拉沙凯斯。','我可不信任领主拉沙凯斯。'),
(900358,'我希望格伦领主能再补充点人手。','我希望格伦领主能再补充点人手。'),
(900359,'别和我说话，我现在处于警戒状态!','别和我说话，我现在处于警戒状态!');
