INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(417,0,0,'什么是地下城？','',1),
(417,0,1,'我该如何更改地下城设定？','',2),
(417,0,2,'“重置所有地下城”按键？那是什么？','',3),
(417,0,3,'什么是传奇模式？什么是疲劳度？','',4);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900431,'我们已经到了。$B$B祭坛就在前方。你准备好了吗？','我们已经到了。$B$B祭坛就在前方。你准备好了吗？');
