INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900485,'这座岛上发生了什么？我们本想过上更美好的生活，但却被困于此处。','这座岛上发生了什么？我们本想过上更美好的生活，但却被困于此处。');
