INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(472,0,900511,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900494,'Ненавижу, когда наши вечеринки называют скучными! Разве тут скучно? Просто пей и веселись - вот наш девиз!','Ненавижу, когда наши вечеринки называют скучными! Разве тут скучно? Просто пей и веселись - вот наш девиз!');
