INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(473,0,900512,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900495,'我是阿诺德，辛斯卡德最伟大的地下城大师。$B我能够让你的属性得到短暂提升，持续2小时！$B选择你想战士提升的属性，$C！','我是阿诺德，辛斯卡德最伟大的地下城大师。$B我能够让你的属性得到短暂提升，持续2小时！$B选择你想战士提升的属性，$C！');
