INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900563,'Здравствуйте, куда вы хоте ли бы отправиться? Я помогу вам, расскажите только, куда вы хотите попасть.','Здравствуйте, куда вы хоте ли бы отправиться? Я помогу вам, расскажите только, куда вы хотите попасть.');
