(568,0,900640,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900586,'除了那些种族限定坐骑，哈拉顿还有各种各样的通用坐骑。通用坐骑只要求玩家学会任意骑术便可骑乘。','除了那些种族限定坐骑，哈拉顿还有各种各样的通用坐骑。通用坐骑只要求玩家学会任意骑术便可骑乘。');
