INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900644,'你相信卡林吗？','你相信卡林吗？'),
(900645,'霜原是我们的家乡。','霜原是我们的家乡。'),
(900646,'我们相遇过吗？你那$R的脸看上去很眼熟。','我们相遇过吗？你那$R的脸看上去很眼熟。'),
(900647,'极地蛮人族在数个世纪以前就成为了我们的敌人。','极地蛮人族在数个世纪以前就成为了我们的敌人。'),
(900648,'我们是最好的斗士。','我们是最好的斗士。'),
(900649,'我想喝酒和狩猎。','我想喝酒和狩猎。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900743,900644,0.16666667,900645,0.16666667,900646,0.16666667,900647,0.16666667,900648,0.16666667,900649,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(643,0,900743,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900650,'我见到过你们族群的许多女战士。很高兴见到你们的女士与我们的女士一样强壮。','我见到过你们族群的许多女战士。很高兴见到你们的女士与我们的女士一样强壮。'),
(900651,'呆在这儿，你会很安全的，小兄弟。','呆在这儿，你会很安全的，小兄弟。'),
(900652,'如果我是你，我会呆在营地里。','如果我是你，我会呆在营地里。'),
(900653,'愿卡林保佑你，$R。','愿卡林保佑你，$R。'),
(900654,'站完这班岗，我就去喝个够。','站完这班岗，我就去喝个够。');
