INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900656,'乐意效劳。','乐意效劳。'),
(900657,'武器饥渴难耐了。','武器饥渴难耐了。'),
(900658,'祖先指引你的道路。','祖先指引你的道路。'),
(900659,'你是真正的朋友。','你是真正的朋友。'),
(900660,'干得好。今天的工作已经完成了。','干得好。今天的工作已经完成了。'),
(900661,'我们准备好了。','我们准备好了。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900747,900656,0.16666667,900657,0.16666667,900658,0.16666667,900659,0.16666667,900660,0.16666667,900661,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(647,0,900747,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900662,'需要我效劳吗？','需要我效劳吗？'),
(900663,'洗耳恭听。','洗耳恭听。'),
(900664,'很高兴见到你。','很高兴见到你。'),
(900665,'别着急。其他人能帮助你。','别着急。其他人能帮助你。'),
(900666,'亮光。如此明亮。','亮光。如此明亮。'),
(900667,'累啊，累啊，太累了。','累啊，累啊，太累了。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900748,900662,0.16666667,900663,0.16666667,900664,0.16666667,900665,0.16666667,900666,0.16666667,900667,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(648,0,900748,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900668,'我们不喜欢冰原人，但更憎恶恶魔。','我们不喜欢冰原人，但更憎恶恶魔。'),
(900669,'对什么都很小心！不然会被抢！','对什么都很小心！不然会被抢！'),
(900670,'你有金币？我这儿有个历史悠久的骨头护符可以卖给你。保证不是我今天吃剩的！','你有金币？我这儿有个历史悠久的骨头护符可以卖给你。保证不是我今天吃剩的！'),
(900671,'下次吧，我们一起去找个落单的冰原人抢一抢。','下次吧，我们一起去找个落单的冰原人抢一抢。'),
(900672,'我在找可以打劫的外族合伙人……不，我是说，我在站岗。','我在找可以打劫的外族合伙人……不，我是说，我在站岗。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900749,900668,0.16666667,900669,0.16666667,900648,0.16666667,900670,0.16666667,900671,0.16666667,900672,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(649,0,900749,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900673,'你认为冰原人愿意接纳我们，和我们一起生活？我很怀疑。','你认为冰原人愿意接纳我们，和我们一起生活？我很怀疑。'),
(900674,'我喜欢鱼；我讨厌钓鱼。','我喜欢鱼；我讨厌钓鱼。'),
(900675,'你是来与恶魔战斗的？不是和我们？好极了。我们会为你提供援助。','你是来与恶魔战斗的？不是和我们？好极了。我们会为你提供援助。'),
(900676,'唔，看过了你们族群的许多人，只有你顺眼点。','唔，看过了你们族群的许多人，只有你顺眼点。'),
(900677,'我想如果你个头更矮，肌肉更发达，你还能帅一点。','我想如果你个头更矮，肌肉更发达，你还能帅一点。'),
(900678,'你的钱包一直在引诱我们；好好放着吧！','你的钱包一直在引诱我们；好好放着吧！');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900750,900673,0.16666667,900674,0.16666667,900675,0.16666667,900676,0.16666667,900677,0.16666667,900678,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(650,0,900750,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900679,'黑暗精灵是地下疆域的唯一主人。','黑暗精灵是地下疆域的唯一主人。'),
(900680,'$R，额？别闯祸。','$R，额？别闯祸。'),
(900681,'别叫我们什么乱七八糟的名字。叫黑暗精灵，谢谢。','别叫我们什么乱七八糟的名字。叫黑暗精灵，谢谢。'),
(900682,'对于那些非黑暗精灵的族裔，地下疆域是真正残酷的试炼。','对于那些非黑暗精灵的族裔，地下疆域是真正残酷的试炼。'),
(900683,'别烦我，外族人。','别烦我，外族人。'),
(900684,'你的穿着就像是斗士。我很好奇你的行为是否能像你的穿着一样令人印象深刻。','你的穿着就像是斗士。我很好奇你的行为是否能像你的穿着一样令人印象深刻。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
(900751,900679,0.16666667,900680,0.16666667,900681,0.16666667,900682,0.16666667,900683,0.16666667,900684,0.16666667,0,0,0,0);
INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(651,0,900751,'');
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900685,'最近几个月，来了不少我们见所未见的陌生人。我在想这是好事吗……','最近几个月，来了不少我们见所未见的陌生人。我在想这是好事吗……'),
(900686,'我厌倦了这该死的职责！我只希望战争能快点结束。','我厌倦了这该死的职责！我只希望战争能快点结束。'),
(900687,'我的舌头和武器都不欢迎你，外族人。','我的舌头和武器都不欢迎你，外族人。'),
(900688,'学习我们的生活方式；你可以在地下疆域活得久一点。','学习我们的生活方式；你可以在地下疆域活得久一点。'),
(900689,'只要是冷环需要的东西，即使是大地也得卑躬屈膝。','只要是冷环需要的东西，即使是大地也得卑躬屈膝。'),
(900690,'你为什么一直在给我惹麻烦，$R？','你为什么一直在给我惹麻烦，$R？');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
