INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900747,'你在锦标赛中获得的奖励将发送至你的邮箱——仔细检查一下吧！','你在锦标赛中获得的奖励将发送至你的邮箱——仔细检查一下吧！');
