INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900778,'来看啊，来瞧啊！来看看这些甜甜的，有魔力的糖果！包您满意！','来看啊，来瞧啊！来看看这些甜甜的，有魔力的糖果！包您满意！');
