(788,0,900907,'');
INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(788,0,0,'好，走吧。','1',-1),
(788,0,1,'再等等……','',-1);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900814,'你好，我的朋友，愿阴影将你隐藏。隐藏是一个礼物，也是一个诅咒。你可以利用阴影，但同样有时候，你只能待在阴影中。这个试炼的目标很简单：杀死帐篷中的那个人。从前，他与恶魔做了一桩交易，将把遗忘带到我们的世界。我们最伟大的刺客击败了他，拯救了世界。现在该你了。准备好了吗，我的朋友？','你好，我的朋友，愿阴影将你隐藏。隐藏是一个礼物，也是一个诅咒。你可以利用阴影，但同样有时候，你只能待在阴影中。这个试炼的目标很简单：杀死帐篷中的那个人。从前，他与恶魔做了一桩交易，将把遗忘带到我们的世界。我们最伟大的刺客击败了他，拯救了世界。现在该你了。准备好了吗，我的朋友？');
