INSERT INTO `m425_menu_variant` (`menu`,`variant`,`npc_text`,`conditions`) VALUES
(806,0,900928,'');
INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(806,0,0,'这世上有许多不公平的事。贫穷、战争、疾病、死亡……你没法一下子就改变它们，但可以尽力而为，坚持不懈。','',1),
(806,0,1,'男人在童年时总被女人欺负。','',2),
(806,0,2,'呃……','',-1);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900830,'真难以置信，我之前竟然还以为你是个聪明人。','真难以置信，我之前竟然还以为你是个聪明人。');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
