INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(813,0,0,'是的，我们这就开始追击吧。','1',-1),
(813,0,1,'稍等一下……','',-1);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900837,'什么？你知道吗，我有很多兄弟！喂，又不是所有的哥布林都是贼，你懂吧兄弟。只是因为某些坏家伙偷了所有的礼物——噢，你只是想去游乐园？干嘛不早说呢？！哼。','什么？你知道吗，我有很多兄弟！喂，又不是所有的哥布林都是贼，你懂吧兄弟。只是因为某些坏家伙偷了所有的礼物——噢，你只是想去游乐园？干嘛不早说呢？！哼。');
