INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900922,'你不想要提示。$B你不需要提示。$B红色饥饿，蓝色死去。$B黄色孤单却无人问津。','你不想要提示。$B你不需要提示。$B红色饥饿，蓝色死去。$B黄色孤单却无人问津。');
