INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900953,'I\'ve lived here all my life -- and nothing about this forest is driving anyone insane. Fairy tales are just that -- fairy tales and old wives\' tales. I\'m an old widow, so I should know, mind you.','I\'ve lived here all my life -- and nothing about this forest is driving anyone insane. Fairy tales are just that -- fairy tales and old wives\' tales. I\'m an old widow, so I should know, mind you.');
INSERT INTO `npc_text` (`ID`,`BroadcastTextID0`,`Probability0`,`BroadcastTextID1`,`Probability1`,`BroadcastTextID2`,`Probability2`,`BroadcastTextID3`,`Probability3`,`BroadcastTextID4`,`Probability4`,`BroadcastTextID5`,`Probability5`,`BroadcastTextID6`,`Probability6`,`BroadcastTextID7`,`Probability7`) VALUES
