INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(984,1,0,'I understand.','',1);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(900954,'Now, I\'ve seen those clerics, and they\'re definitely acting strange. But it\'s not the forest; it\'s got to be something else. But it really doesn\'t matter what it is, you see, because nothing from the outside can turn a man crazy. No, only what\'s on the inside can do that.','Now, I\'ve seen those clerics, and they\'re definitely acting strange. But it\'s not the forest; it\'s got to be something else. But it really doesn\'t matter what it is, you see, because nothing from the outside can turn a man crazy. No, only what\'s on the inside can do that.');
