INSERT INTO `m425_menu_option` (`menu`,`variant`,`option`,`label`,`scripts`,`link`) VALUES
(1080,0,0,'厨师学徒：在你烹饪火鸡之后，你会从合金通灵塔和幻灵梦境地下城获得一些锃亮的器具，你还有机会在这些地点获得绝密的史诗级器具！','1',-1),
(1080,0,1,'厨师：在你烹饪火鸡之后，你会从烈焰地下城获得一些锃亮的器具，你还有机会在此地点获得绝密的史诗级器具！','2',-1),
(1080,0,2,'主厨：在你烹饪火鸡之后，你会从烈焰崛起地下城获得一些锃亮的器具，你还有机会在此地点获得绝密的史诗级器具！','3',-1);
