INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`) VALUES
(901214,'虽然索西莉亚残酷无情，但泰兰西亚却人美心善。你也想伤害她吗？','虽然索西莉亚残酷无情，但泰兰西亚却人美心善。你也想伤害她吗？');
